 async function sendAndReceive(
   socket: WebSocket,
   message: string | Uint8Array,
   timeoutMs = SOCKET_SETUP_TIMEOUT_MS,
 ): Promise<string | ArrayBuffer> {
   const response = receiveMessage(socket, timeoutMs);
   socket.send(message);
   return response;
